/**
 * MEDICAL_RECORDS q9 oscillated across identical runs from a clean learned state (220ms - 1644ms - 667ms - ...,
 * 2026-08-04): completed-query feedback flipped a near-tied anti-join choice every run and priced the correlated
 * probe's outer input at ~2 rows. This guards the fixed steady state: repeated runs with learning live stay in one
 * execution performance class and no plan ever prices the MINUS probe's outer rows at a crushed fraction of its input.
 * Query open time is reported separately because a later certified packed-plan cache hit must not retroactively
 * classify earlier full replanning passes as execution regressions.
 */
class LmdbMedicalQ9PlanStabilityIT {

	private static final Theme THEME = Theme.MEDICAL_RECORDS;
	private static final int QUERY_INDEX = 9;
	private static final int RUNS = 6;
	private static final int LEARNING_SUPPORT_RUNS = 32;
	private static final int MAX_EXECUTION_TIME_SECONDS = 60;
	// The oscillation produced ~7.5x execution excursions (220ms vs 1644ms); ordinary noise stays well below this.
	private static final double MAX_EXECUTION_SLOWDOWN_VS_PRIOR_FASTEST = 5.0d;
	private static final long ABSOLUTE_SLACK_NANOS = TimeUnit.MILLISECONDS.toNanos(400);
	private static final double MIN_CORRELATION_OUTER_ROWS = 300.0d;
	private static final Pattern OUTER_ROWS = Pattern.compile("plannedCorrelationOuterRows=([0-9.,]+[KM]?)");
	private static final Pattern SEMI_ANTI_ALGORITHM = Pattern.compile("optimizer\\.semiAntiAlgorithm=([^,)]+)");
	private static final Pattern LOGICAL_DIGEST = Pattern.compile("optimizer\\.logicalLearningKeyDigest=([^,)]+)");
	private static final Pattern APPLICABILITY_DIGEST = Pattern
			.compile("optimizer\\.learningApplicabilityDigest=([^,)]+)");
	private static final Pattern PHYSICAL_DIGEST = Pattern.compile("optimizer\\.physicalResidualKeyDigest=([^,)]+)");
	private static final Pattern LIFECYCLE_STATE = Pattern.compile("optimizer\\.lifecycleState=([^,)]+)");
	private static final Pattern LOGICAL_EXACT_EVIDENCE = Pattern
			.compile("optimizer\\.frontierLeo\\.output_rows\\.exactEvidence=([0-9.,]+[KM]?)");
	private static final Pattern LOGICAL_EXACT_FACT = Pattern
			.compile("optimizer\\.frontierLeo\\.output_rows\\.source=exact-fact");
	private static final Path REPORT_PATH = BenchmarkPathSupport.resolveTarget("medical-q9-plan-stability.txt");

	@Test
	@Timeout(value = 20, unit = TimeUnit.MINUTES)
	void q9StaysInOnePerformanceClassAcrossLearningRuns() throws Exception {
		String previousProfile = System.setProperty(
				LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, "safe-cardinality-correction");
		try (var ignored = BenchmarkJoinEstimatorSupport.forceDefaultPackedOptimizerMode()) {
			ThemeQueryBenchmark benchmark = newBenchmark();
			deleteLearnedSidecars();
			benchmark.setup();
			try {
				String query = ThemeQueryCatalog.queryFor(THEME, QUERY_INDEX);
				long expectedCount = ThemeQueryCatalog.expectedCountBindingValueFor(THEME, QUERY_INDEX)
						.orElseThrow();
				long[] elapsedNanos = new long[RUNS];
				long[] executionNanos = new long[RUNS];
				StringBuilder report = new StringBuilder("MEDICAL_RECORDS q9 plan stability (" + RUNS + " runs)\n");
				for (int run = 0; run < RUNS; run++) {
					report.append("run ").append(run).append(": started\n");
					writeReport(report.toString());
					System.out.print("MEDICAL_RECORDS q9 run " + run + " started\n");
					long started = System.nanoTime();
					ThemeQueryBenchmark.TimedCountQuery timing = benchmark.executeTimedCountQuery(
							query, expectedCount, MAX_EXECUTION_TIME_SECONDS);
					long count = timing.countBindingValue();
					elapsedNanos[run] = System.nanoTime() - started;
					executionNanos[run] = timing.consumptionNanos();
					assertEquals(expectedCount, count, "run " + run);
					String plan = benchmark.explainOptimizedPlan(query);
					writePlan(run, plan);
					List<Double> outerRows = correlationOuterRows(plan);
					report.append(String.format(Locale.ROOT,
							"run %d: %.1f ms (prepare=%.1f, open=%.1f, consume=%.1f), outerRows=%s, semiAnti=%s, finiteCondCode=%s%n",
							run, elapsedNanos[run] / 1_000_000.0d, timing.preparationNanos() / 1_000_000.0d,
							timing.openNanos() / 1_000_000.0d, timing.consumptionNanos() / 1_000_000.0d,
							outerRows, semiAntiPlans(plan),
							plan.contains("selected=values-anchor:condCode")));
					writeReport(report.toString());
					System.out.printf(Locale.ROOT, "MEDICAL_RECORDS q9 run %d completed in %.1f ms%n",
							run, elapsedNanos[run] / 1_000_000.0d);
					for (double rows : outerRows) {
						assertTrue(rows >= MIN_CORRELATION_OUTER_ROWS,
								() -> "A learned run re-planned the MINUS probe with crushed outer rows (" + rows
										+ ") — the q9 poison shape: \n" + report + "\n" + plan);
					}
					List<String> lifecycleStates = lifecycleStates(plan);
					assertTrue(!lifecycleStates.isEmpty() && lifecycleStates.stream().allMatch("monitoring"::equals),
							() -> "The default rollout must expose Monitoring-only lifecycle decisions, but found "
									+ lifecycleStates + ":\n" + plan);
				}
				writeReport(report.toString());
				System.out.println(report);
				// Run 0 is excluded: it pays execution warmup. Run 1 establishes the first learned execution.
				// Thereafter a later learned plan may improve, but it must not regress from the best execution that
				// has already completed and verified. Optimizer/open time is assessed by the dedicated planning
				// benchmark.
				long priorFastestExecution = executionNanos[1];
				for (int run = 2; run < RUNS; run++) {
					assertTrue(executionNanos[run] <= priorFastestExecution
							* MAX_EXECUTION_SLOWDOWN_VS_PRIOR_FASTEST + ABSOLUTE_SLACK_NANOS,
							"run " + run + " left the verified execution performance class:\n" + report);
					priorFastestExecution = Math.min(priorFastestExecution, executionNanos[run]);
				}
			} finally {
				benchmark.tearDown();
			}
		} finally {
			restoreProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, previousProfile);
		}
	}

	@Test
	@Timeout(value = 10, unit = TimeUnit.MINUTES)
	void interleavedQ9AndQ10KeepIncompatibleLearningStateIsolated() throws Exception {
		String previousProfile = System.setProperty(
				LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, "safe-cardinality-correction");
		try (var ignored = BenchmarkJoinEstimatorSupport.forceDefaultPackedOptimizerMode()) {
			ThemeQueryBenchmark benchmark = newBenchmark();
			deleteLearnedSidecars();
			benchmark.setup();
			try {
				String q9 = ThemeQueryCatalog.queryFor(THEME, 9);
				String q10 = ThemeQueryCatalog.queryFor(THEME, 10);
				long q9Count = expectedCount(9);
				long q10Count = expectedCount(10);

				trainToMinimumSupport(benchmark, q9, q9Count);
				String learnedQ9Plan = benchmark.explainOptimizedPlan(q9);
				Set<LearningIdentity> q9Identities = learningIdentities(learnedQ9Plan);
				assertTrue(!q9Identities.isEmpty(), learnedQ9Plan);

				String q10AfterQ9 = benchmark.explainOptimizedPlan(q10);
				Set<LearningIdentity> q10ReusedEvidence = learnedLogicalIdentities(q10AfterQ9);
				assertTrue(q9Identities.containsAll(q10ReusedEvidence),
						() -> "q10 consumed learned evidence outside q9's exact logical/applicability identities: "
								+ q10ReusedEvidence + " versus " + q9Identities + "\n" + q10AfterQ9);

				assertEquals(q10Count, benchmark.executeCountQuery(q10, q10Count, MAX_EXECUTION_TIME_SECONDS));
				assertEquals(q9Count, benchmark.executeCountQuery(q9, q9Count, MAX_EXECUTION_TIME_SECONDS));
				String q9AfterQ10 = benchmark.explainOptimizedPlan(q9);
				assertSafeQ9Plan(q9AfterQ10);
				assertTrue(learningIdentities(q9AfterQ10).stream().anyMatch(q9Identities::contains),
						"Interleaving q10 must not orphan q9's exact logical identity");
			} finally {
				benchmark.tearDown();
			}
		} finally {
			restoreProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, previousProfile);
		}
	}

	@Test
	@Timeout(value = 10, unit = TimeUnit.MINUTES)
	void q9LearningAndLifecycleSurviveStoreRestart() throws Exception {
		String previousProfile = System.setProperty(
				LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, "safe-cardinality-correction");
		try (var ignored = BenchmarkJoinEstimatorSupport.forceDefaultPackedOptimizerMode()) {
			deleteLearnedSidecars();
			String query = ThemeQueryCatalog.queryFor(THEME, QUERY_INDEX);
			long expectedCount = expectedCount(QUERY_INDEX);
			Set<LearningIdentity> trainedIdentities;
			ThemeQueryBenchmark trainer = newBenchmark();
			trainer.setup();
			try {
				trainToMinimumSupport(trainer, query, expectedCount);
				trainedIdentities = learnedLogicalIdentities(trainer.explainOptimizedPlan(query));
				assertTrue(!trainedIdentities.isEmpty(),
						"The completed q9 execution must produce learned logical state");
			} finally {
				trainer.tearDown();
			}

			Path sidecar = learnedSidecar("join-estimator.rjes.operators");
			assertTrue(Files.isRegularFile(sidecar), "Store shutdown must persist the learned-feedback sidecar");
			assertEquals(23, ByteBuffer.wrap(Files.readAllBytes(sidecar)).getInt(),
					"Restart acceptance requires the statement-stamped v23 sidecar");

			ThemeQueryBenchmark restarted = newBenchmark();
			restarted.setup();
			try {
				String restartedPlan = restarted.explainOptimizedPlan(query);
				Set<LearningIdentity> restoredIdentities = learnedLogicalIdentities(restartedPlan);
				assertTrue(restoredIdentities.stream().anyMatch(trainedIdentities::contains),
						() -> "Restart must restore q9's exact logical evidence: " + trainedIdentities + " versus "
								+ restoredIdentities + "\n" + restartedPlan);
				assertSafeQ9Plan(restartedPlan);
				assertEquals(expectedCount,
						restarted.executeCountQuery(query, expectedCount, MAX_EXECUTION_TIME_SECONDS));
			} finally {
				restarted.tearDown();
			}
		} finally {
			restoreProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, previousProfile);
		}
	}

	private static ThemeQueryBenchmark newBenchmark() {
		ThemeQueryBenchmark benchmark = new ThemeQueryBenchmark();
		benchmark.themeName = THEME.name();
		benchmark.z_queryIndex = QUERY_INDEX;
		benchmark.sketchEstimatorEnabled = true;
		benchmark.loadOnlySelectedTheme = true;
		return benchmark;
	}

	private static void trainToMinimumSupport(ThemeQueryBenchmark benchmark, String query, long expectedCount)
			throws Exception {
		for (int run = 0; run < LEARNING_SUPPORT_RUNS; run++) {
			assertEquals(expectedCount,
					benchmark.executeCountQuery(query, expectedCount, MAX_EXECUTION_TIME_SECONDS));
		}
	}

	private static long expectedCount(int queryIndex) {
		return ThemeQueryCatalog.expectedCountBindingValueFor(THEME, queryIndex).orElseThrow();
	}

	/** A clean learned state: the loaded store may exist, but no learned sidecar survives into run 0. */
	private static void deleteLearnedSidecars() throws IOException {
		File storeDirectory = benchmarkStoreDirectory().toFile();
		if (!storeDirectory.isDirectory()) {
			return;
		}
		for (String sidecar : new String[] { "join-estimator.rjes.operators", "join-estimator.rjes.filters" }) {
			Files.deleteIfExists(storeDirectory.toPath().resolve(sidecar));
		}
	}

	private static Path benchmarkStoreDirectory() {
		return BenchmarkPathSupport.resolveTarget("lmdb-theme-query-benchmark")
				.resolve(THEME.name().toLowerCase(Locale.ROOT) + "-only");
	}

	private static Path learnedSidecar(String name) {
		return benchmarkStoreDirectory().resolve(name);
	}

	private static List<Double> correlationOuterRows(String plan) {
		List<Double> values = new ArrayList<>();
		Matcher matcher = OUTER_ROWS.matcher(plan);
		while (matcher.find()) {
			values.add(parseAbbreviated(matcher.group(1)));
		}
		return values;
	}

	private static List<String> semiAntiPlans(String plan) {
		List<String> values = new ArrayList<>();
		plan.lines()
				.filter(line -> line.contains("optimizer.semiAntiAlgorithm="))
				.forEach(line -> values.add("algorithm=" + metric(SEMI_ANTI_ALGORITHM, line)
						+ ",logical=" + metric(LOGICAL_DIGEST, line)
						+ ",applicability=" + metric(APPLICABILITY_DIGEST, line)
						+ ",physical=" + metric(PHYSICAL_DIGEST, line)
						+ ",lifecycle=" + metric(LIFECYCLE_STATE, line)));
		return values;
	}

	private static List<String> lifecycleStates(String plan) {
		return plan.lines()
				.filter(line -> line.contains("optimizer.semiAntiAlgorithm="))
				.map(line -> metric(LIFECYCLE_STATE, line))
				.toList();
	}

	private static Set<LearningIdentity> learningIdentities(String plan) {
		Set<LearningIdentity> identities = new LinkedHashSet<>();
		plan.lines().forEach(line -> {
			String logical = metric(LOGICAL_DIGEST, line);
			String applicability = metric(APPLICABILITY_DIGEST, line);
			if (!"missing".equals(logical) && !"missing".equals(applicability)) {
				identities.add(new LearningIdentity(logical, applicability));
			}
		});
		return identities;
	}

	private static Set<LearningIdentity> learnedLogicalIdentities(String plan) {
		Set<LearningIdentity> identities = new LinkedHashSet<>();
		plan.lines().forEach(line -> {
			String evidence = metric(LOGICAL_EXACT_EVIDENCE, line);
			boolean exactFact = LOGICAL_EXACT_FACT.matcher(line).find();
			if (!exactFact && ("missing".equals(evidence) || parseAbbreviated(evidence) <= 0.0d)) {
				return;
			}
			String logical = metric(LOGICAL_DIGEST, line);
			String applicability = metric(APPLICABILITY_DIGEST, line);
			if (!"missing".equals(logical) && !"missing".equals(applicability)) {
				identities.add(new LearningIdentity(logical, applicability));
			}
		});
		return identities;
	}

	private static void assertSafeQ9Plan(String plan) {
		List<Double> outerRows = correlationOuterRows(plan);
		List<String> algorithms = semiAntiAlgorithms(plan);
		boolean materializedWinner = algorithms.stream().anyMatch(algorithm -> algorithm.startsWith("materialized"));
		boolean semanticMinus = plan.contains("Difference")
				|| plan.contains("optimizer.semiAntiKind=minus-assured-shared");
		assertTrue(semanticMinus && (materializedWinner || !outerRows.isEmpty()),
				() -> "q9 must retain a semantic MINUS with either a materialized winner or an explicit correlated outer "
						+ "estimate after learning:\n" + plan);
		assertTrue(outerRows.stream().allMatch(rows -> rows >= MIN_CORRELATION_OUTER_ROWS),
				() -> "q9 must never use a crushed correlated outer estimate after learning:\n" + plan);
		List<String> lifecycleStates = lifecycleStates(plan);
		assertTrue(!lifecycleStates.isEmpty() && lifecycleStates.stream().allMatch("monitoring"::equals),
				() -> "The default rollout must remain Monitoring-only, but found " + lifecycleStates + ":\n" + plan);
	}

	private static List<String> semiAntiAlgorithms(String plan) {
		return plan.lines()
				.filter(line -> line.contains("optimizer.semiAntiAlgorithm="))
				.map(line -> metric(SEMI_ANTI_ALGORITHM, line))
				.toList();
	}

	private static String metric(Pattern pattern, String line) {
		Matcher matcher = pattern.matcher(line);
		return matcher.find() ? matcher.group(1) : "missing";
	}

	private static double parseAbbreviated(String value) {
		String cleaned = value.replace(",", "");
		double multiplier = 1.0d;
		if (cleaned.endsWith("K")) {
			multiplier = 1_000.0d;
			cleaned = cleaned.substring(0, cleaned.length() - 1);
		} else if (cleaned.endsWith("M")) {
			multiplier = 1_000_000.0d;
			cleaned = cleaned.substring(0, cleaned.length() - 1);
		}
		return Double.parseDouble(cleaned) * multiplier;
	}

	private static void writeReport(String report) throws IOException {
		Files.createDirectories(REPORT_PATH.getParent());
		Files.writeString(REPORT_PATH, report, StandardCharsets.UTF_8);
	}

	private static void writePlan(int run, String plan) throws IOException {
		Path path = REPORT_PATH.resolveSibling("medical-q9-plan-stability-run-" + run + ".txt");
		Files.createDirectories(path.getParent());
		Files.writeString(path, plan, StandardCharsets.UTF_8);
	}

	private static void restoreProperty(String name, String previous) {
		if (previous == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, previous);
		}
	}

	private record LearningIdentity(String logicalDigest, String applicabilityDigest) {
	}
}
